<script setup lang="ts">
import {ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import StatePanel from '../../../components/StatePanel.vue'
import {personalAgent as agent} from '../../../utils/personal-agent'
import {reportsApi} from '../../../api/reports'
import {useUserStore} from '../../../stores/user'
import {requireRole,landing,go} from '../../../utils/navigation'
import {errorText,toast} from '../../../utils/format'
import type {ReportListItem} from '../../../types/report-list'
import type {AgentSource} from '../../../types/agent'
const {context,conversations,conversationId,title,turns,error,loading,pending,busy,hasMore,historyMore}=agent
const input=ref(''),historyVisible=ref(false),reportVisible=ref(false),reports=ref<ReportListItem[]>([]),reportMore=ref(false),reportLoading=ref(false),reportError=ref(''),selected=ref<{reportId:string;revision:number;title:string;candidate:boolean}>(),keyboard=ref(0)
let reportPage=0,visible=false,routeReport='',routeRevision=0
watch(context,value=>{if(!value){selected.value=undefined;reports.value=[];historyVisible.value=false;reportVisible.value=false;input.value=''}})
async function initialize(){if(!await requireRole('worker')||!visible)return;await agent.initialize();if(!visible)return;if(!context.value&&error.value){await useUserStore().refresh().catch(()=>{});const p=useUserStore().profile;if(p&&landing(p)!=='/pages/worker/home/index')uni.reLaunch({url:landing(p)})}}
onLoad(q=>{routeReport=q?.reportId||'';routeRevision=Number(q?.revision||0);uni.onNetworkStatusChange(network)})
onShow(async()=>{visible=true;await initialize();if(routeReport&&routeRevision>0){try{const r=await reportsApi.detail(routeReport,routeRevision);if(visible&&r.rawStatus!=='rejected')selected.value={reportId:r.id,revision:r.revision!,title:r.title,candidate:!!r.candidate}}catch(e){toast(errorText(e))}routeReport=''}})
function hide(){visible=false;agent.hide()}
function network(e:{isConnected:boolean}){if(!e.isConnected)agent.hide();else if(visible)agent.resume()}
onHide(hide);onUnload(()=>{hide();uni.offNetworkStatusChange(network)})
async function send(text?:string){const value=(text||input.value).trim();if(!value||busy.value||loading.value)return;await agent.send(value,selected.value?{reportId:selected.value.reportId,revision:selected.value.revision}:undefined);if(!error.value||pending.value)input.value=''}
async function openHistory(id:string){await agent.open(id);historyVisible.value=false;selected.value=undefined}
function newChat(){agent.newChat();selected.value=undefined;input.value='';historyVisible.value=false}
async function loadReports(more=false){if(reportLoading.value)return;reportLoading.value=true;reportError.value='';try{const page=more?reportPage+1:1,r=await reportsApi.paginatedList('all',page,10);if(!visible)return;reports.value=more?[...reports.value,...r.items]:r.items;reportPage=page;reportMore.value=r.hasMore}catch(e){reportError.value=errorText(e)}finally{reportLoading.value=false}}
function chooseReport(r:ReportListItem){if(r.status==='rejected'){toast('已驳回报告不能用于候选解读');return}selected.value={reportId:r.reportId,revision:r.revision,title:r.title||r.fileName||'体检报告',candidate:!r.approved};reportVisible.value=false}
function showReports(){if(busy.value||loading.value)return;reportVisible.value=true;loadReports()}
function sourceLink(s:AgentSource){if(s.reportId&&Number.isInteger(s.revision)&&s.revision>0)go('/pages/worker/report-detail/index?id='+encodeURIComponent(s.reportId)+'&revision='+s.revision)}
function remove(){if(!conversationId.value||busy.value||loading.value)return;const id=conversationId.value;uni.showModal({title:'删除当前对话',content:'删除后不可恢复，不会删除您的健康档案或体检报告。',success:async r=>{if(r.confirm)try{await agent.remove(id);toast('对话已删除')}catch(e){toast(errorText(e))}}})}
</script>
<template><PageShell :title="context?.assistantName||'我的 AI 健康师'" :back="false" tab="assistant">
 <view class="chat-toolbar"><text>本人健康分析</text><view class="flex gap"><text @tap="historyVisible=!historyVisible">历史对话</text><text v-if="conversationId" @tap="remove">删除</text><text @tap="newChat">＋ 新对话</text></view></view>
 <view class="agent-body">
 <StatePanel :loading="loading&&!context" :error="!context?error:''" @retry="initialize"/>
 <view v-if="context&&!context.enabled" class="alert">个人健康师暂不可用，请稍后刷新。<text @tap="initialize"> 刷新状态</text></view>
 <view v-if="historyVisible" class="card history-panel"><text class="section-title">我的历史对话</text><text v-if="!conversations.length" class="help">暂无历史对话</text><view v-for="s in conversations" :key="s.id" class="row" @tap="!busy&&!loading&&openHistory(s.id)"><text>{{s.title}}</text></view><button v-if="hasMore" class="btn btn-soft small" :disabled="loading||busy" @tap="agent.list(true).catch(e=>toast(errorText(e)))">更多对话</button><text v-if="busy" class="help">请等待当前问题处理结束后切换对话。</text></view>
 <view v-if="reportVisible" class="card report-picker"><view class="between"><text class="section-title">选择本人报告</text><text @tap="reportVisible=false">关闭</text></view><view class="row" @tap="selected=undefined;reportVisible=false">不指定报告，由健康师查询本人已审核报告</view><view v-for="r in reports" :key="r.reportId" class="row" @tap="chooseReport(r)"><view><text>{{r.title||r.fileName||'体检报告'}} · 版本 {{r.revision}}</text><text class="help">{{r.statusText}} {{!r.approved?'· 待审核，仅供核对':''}}</text></view></view><text v-if="reportError" class="failure">{{reportError}}</text><button v-if="reportError" class="btn btn-soft small" @tap="loadReports()">重试读取报告</button><button v-if="reportMore" class="btn btn-soft small" :loading="reportLoading" @tap="loadReports(true)">更多报告</button><text v-if="!reportLoading&&!reportError&&!reports.length" class="help">暂无报告</text></view>
 <scroll-view scroll-y class="chat-scroll" :style="keyboard?{height:'calc(100vh - '+(290+keyboard)+'px)'}:{}">
 <view class="chat-content"><template v-if="!turns.length&&!pending"><view class="assistant-welcome"><view class="robot-halo"><AppIcon name="bot" :size="50"/></view><text class="welcome-title">您好，今天想了解些什么？</text><text class="welcome-subtitle">解读本人报告，关注职业健康</text></view><view v-for="q in context?.suggestions||[]" :key="q" class="question" @tap="send(q)"><text>{{q}}</text><AppIcon name="chevron-right" color="gray" :size="15"/></view></template>
 <text v-if="conversationId" class="help">{{title}}</text><button v-if="historyMore" class="btn btn-soft small" :disabled="loading||busy" @tap="agent.open(conversationId,true)">加载更早消息</button>
 <view v-for="t in turns" :key="t.messageId" class="agent-turn"><view class="user-question"><text selectable>{{t.question||'历史问题'}}</text></view><view class="agent-answer"><text v-if="t.status==='completed'" selectable>{{t.answer||'后台未返回回答内容'}}</text><text v-else-if="t.status==='failed'" class="failure">{{t.message||'本次分析失败，请稍后重试'}}{{t.errorCode?'（'+t.errorCode+'）':''}}</text><text v-else class="help">{{t.status==='queued'?'问题已受理，正在排队…':'健康师正在分析…'}}</text><view v-for="s in t.sources||[]" :key="s.key||s.reportId+':'+s.revision" class="agent-source" @tap="sourceLink(s)"><text :class="{failure:s.candidate}">{{s.candidate?'待审核，仅供核对':s.reviewStatus==='confirmed'?'医生已审核':'审核状态待核对'}} · {{s.published?'已归档':'未归档'}}</text><text>{{s.examDate||'日期待核对'}} · {{s.institution||'机构未提供'}} · 版本 {{s.revision}}</text><text v-if="s.pageNumbers?.length">来源页码：{{s.pageNumbers.join('、')}}</text><text class="green-text">查看来源报告 ›</text></view><button v-if="t.status==='failed'" class="btn btn-soft small" :disabled="busy||loading||!context?.enabled" @tap="send(t.question)">重新提问</button></view></view>
 <view v-if="pending&&!pending.messageId" class="hint">{{pending.payload.message}}<text class="help">尚未确认后台是否受理。点击重试会沿用原请求标识。</text></view>
 <view v-if="error&&context" class="alert">{{error}}</view><button v-if="pending&&error" class="btn btn-soft small" :disabled="loading" @tap="pending.messageId?agent.resume():agent.send('',undefined,true)">{{pending.messageId?'继续查询回复':'重试原请求'}}</button><button v-if="context&&error&&!pending" class="btn btn-soft small" @tap="initialize">刷新服务状态</button>
 </view></scroll-view></view>
 <view class="chat-composer" :style="keyboard?{bottom:keyboard+'px'}:{}"><view class="report-context" @tap="showReports"><AppIcon name="paperclip" :size="16"/><text>{{selected?'已选：'+selected.title+' · 版本'+selected.revision:'选择本人报告（可选）· 默认查询已审核报告'}}</text><text>⌄</text></view><text v-if="selected?.candidate" class="failure">待审核报告，仅供核对</text><view class="input-line"><input v-model="input" placeholder="输入您想了解的问题…" :maxlength="3000" confirm-type="send" :adjust-position="false" @confirm="send()" @focus="keyboard=($event as any).detail.height||0" @blur="keyboard=0"/><button class="send-btn" :disabled="busy||loading||!context?.enabled||!input.trim()" @tap="send()"><AppIcon :name="busy?'ellipsis':'send'" color="white" :size="21"/></button></view><text class="ai-disclaimer">AI仅供参考，不替代医学诊断；不会修改您的正式档案</text></view>
 </PageShell></template>
<style scoped>.chat-toolbar{display:flex;justify-content:space-between;padding:19rpx 30rpx;background:white;font-size:22rpx;color:#7a9482}.online-dot{height:10rpx;width:10rpx;border-radius:50%;background:#2da775}.toolbar-plus{font-size:32rpx;line-height:1}.chat-scroll{height:calc(100dvh - 330px)}.chat-content{padding:30rpx}.assistant-welcome{display:flex;flex-direction:column;align-items:center;padding:18rpx 0 30rpx}.robot-halo{padding:24rpx;background:radial-gradient(#d2ecdf,#f4faf5);border:8rpx solid #e9f6ec;border-radius:40rpx;margin-bottom:24rpx}.welcome-title{font-size:34rpx;font-weight:650}.welcome-subtitle{font-size:24rpx;color:#8b9c90;margin-top:10rpx}.assistant-intro{font-size:27rpx;padding:25rpx 28rpx}.intro-item{display:flex;align-items:center;gap:14rpx;font-size:25rpx;margin-top:18rpx;color:#607a67}.questions-label{font-size:23rpx;color:#92a194;display:block;margin:28rpx 0 18rpx}.question{display:flex;align-items:center;gap:17rpx;padding:23rpx 22rpx;background:#fff;border:1px solid #eff3ef;border-radius:18rpx;margin-bottom:15rpx}.question>text{flex:1;font-size:25rpx}.chat-composer{position:fixed;bottom:calc(116rpx + env(safe-area-inset-bottom));left:0;right:0;background:#fff;border-top:1px solid #eff3ef;padding:16rpx 25rpx 10rpx;z-index:40;max-width:480px;margin:auto}.report-context{display:flex;gap:10rpx;align-items:center;font-size:21rpx;color:#74a084;margin-bottom:14rpx}.report-context>text:nth-child(2){flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.input-line{display:flex;gap:16rpx;align-items:center}.input-line input{height:86rpx;flex:1;border-radius:40rpx;background:#f3f6f4;padding:22rpx 28rpx;font-size:25rpx;min-width:0}.send-btn{width:84rpx;height:84rpx;min-width:84rpx;flex-shrink:0;padding:0;background:#009358;display:flex;align-items:center;justify-content:center;border-radius:50%}.send-btn[disabled]{background:#668c7c!important;color:#fff;opacity:1;box-shadow:0 0 0 2rpx #527864}.ai-disclaimer{font-size:18rpx;color:#a7b2aa;display:block;text-align:center;margin-top:10rpx}.typing{display:flex;align-items:center;gap:9rpx;font-size:22rpx;color:#94a797;padding:10rpx 0}.typing>view{width:8rpx;height:8rpx;background:#69b488;border-radius:50%;animation:pulse 1s infinite}.typing>view:nth-child(2){animation-delay:.2s}.typing>view:nth-child(3){animation-delay:.4s}@keyframes pulse{50%{opacity:.3}}.agent-body{padding:0 24rpx}.agent-body .chat-scroll{height:calc(100vh - 340px)}.agent-turn{margin:24rpx 0}.user-question{margin-left:55rpx;background:#008f57;color:white;border-radius:22rpx;padding:22rpx;font-size:27rpx;white-space:pre-wrap}.agent-answer{margin-top:18rpx;background:white;border-radius:22rpx;padding:24rpx;font-size:27rpx;line-height:1.8;white-space:pre-wrap;word-break:break-word}.agent-source{margin-top:20rpx;padding-top:16rpx;border-top:1px solid #e5eee8;font-size:22rpx;display:flex;flex-direction:column;color:#6b8475}.failure{display:block;color:#af603c;font-size:23rpx}.history-panel,.report-picker{max-height:450rpx;overflow-y:auto;margin-top:18rpx}</style>
